// PWA web app manifest — Next.js App Router file convention.
//
// Why we have a PWA: it's a home-screen badge that gets dads back to Boss
// Daddy in one tap — the familiar app-icon mental model for quick return to
// the site (reviews, guides, gear). It is NOT a "tools app"; tools are a
// complement, so the icon lands on the homepage, not any single tool.
//
// Icons are pre-rendered, correctly-sized PNGs (generated by downscaling the
// 1024² source app/icon.png — see public/icon-192.png / icon-512.png). The
// maskable variant pads the logo onto a dark tile so Android's adaptive-icon
// circle mask never clips it. The apple-touch-icon is emitted
// separately by Next.js's app/apple-icon.png file convention — don't declare
// it here (it was previously listed with a wrong 180×180 size on a 1024² file).
//
// Launch colors (decided 2026-10-14) — the splash is the PAGE, the status bar is
// the MASTHEAD, the tile is a brand edge:
//  - background_color (splash body) follows the page canvas (lib/canvas.ts): white
//    on the light canvas, so the launch hands straight into the white page with
//    no dark→white flash. The 512 `any` icon is an orange hex on transparent, so
//    the splash reads as the orange hex on white. `BD_CANVAS=dark` restores the
//    dark splash.
//  - theme_color (status bar / task-switcher) is the chrome token #09090b, the
//    same near-black as the masthead that borders the status bar, and matches
//    viewport.themeColor in app/layout.tsx.
//  - The home-screen tile, the maskable icon, and the favicon STAY dark: a tile
//    is a brand edge, not a canvas, so it doesn't follow the page.
// Chrome re-mints the installed WebAPK from this manifest only on reinstall — a
// deploy alone won't change an already-installed app's splash.

import type { MetadataRoute } from 'next'
import { CANVAS } from '@/lib/canvas'

// --color-chrome in app/globals.css (masthead/footer, always this value).
const CHROME = '#09090b'
// The light page canvas (--color-surface on :root).
const LIGHT_CANVAS = '#ffffff'

export default function manifest(): MetadataRoute.Manifest {
  return {
    id:                   '/',
    name:                 'Boss Daddy Life',
    short_name:           'Boss Daddy',
    description:          'Honest gear reviews, guides, and tools for real dads — Boss Daddy, one tap from your home screen.',
    lang:                 'en',
    start_url:            '/',
    scope:                '/',
    display:              'standalone',
    orientation:          'portrait',
    background_color:     CANVAS === 'dark' ? CHROME : LIGHT_CANVAS,
    theme_color:          CHROME,
    categories:           ['lifestyle', 'shopping', 'productivity'],
    // Long-press the home-screen icon → straight to what's due. The icon itself
    // still lands on the homepage (this is not a "tools app"), but a dad who
    // installed it to log a taper shouldn't have to navigate there twice a day.
    // Android surfaces up to 4; keep this list to the things worth a long-press.
    shortcuts: [
      {
        name:       'Today',
        short_name: 'Today',
        url:        '/today',
        description: 'Everything due right now, one tap each.',
      },
      {
        name:       'Goals',
        short_name: 'Goals',
        url:        '/goals',
        description: 'What you\'re working on.',
      },
    ],
    icons: [
      {
        src:     '/icon-192.png',
        sizes:   '192x192',
        type:    'image/png',
        purpose: 'any',
      },
      {
        src:     '/icon-512.png',
        sizes:   '512x512',
        type:    'image/png',
        purpose: 'any',
      },
      {
        src:     '/maskable-512.png',
        sizes:   '512x512',
        type:    'image/png',
        purpose: 'maskable',
      },
    ],
  }
}
